import{J as e,n as t,ot as n,q as r}from"./chunks/framework.BCRZU8Rs.js";var i=JSON.parse(`{"title":"Decisions","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Decisions"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/adr/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/adr/"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/docs/adr"}},"headers":[],"relativePath":"adr/index.md","filePath":"adr/index.md","lastUpdated":1794449216000}`),a={name:`adr/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to “Decisions”">​</a></h1><ul><li><p><strong><a href="./0001-entity-stat-authority.html">Which edition decides an entity stat</a></strong></p><p>Bedrock&#39;s entity definitions and Java Edition&#39;s attribute suppliers publish 438 of the same stats for the same entity, and they disagree on 151 of them.</p></li><li><p><strong><a href="./0002-chunk-generation-architecture.html">Generate a chunk through a status ladder, not a 3 by 3 region</a></strong></p><p><code>DataDrivenGenerator.generateChunk</code> builds a 3 by 3 region, generates terrain for nine chunks, decorates the center, extracts one chunk and serializes the whole body behind one promise, at 1572 ms per chunk.</p></li><li><p><strong><a href="./0003-declarative-wire-layouts.html">Describe a packet&#39;s wire layout as data, once, in the protocol package</a></strong></p><p>A packet whose layout changed at a protocol version is today a sibling class: <code>AnimatePacket2225 extends AnimatePacket</code>, overriding <code>encodePayload</code>/<code>decodePayload</code>, substituted per session by <code>prepareOutbound</code> with an <code>Object.assign</code> copy.</p></li><li><p><strong><a href="./0004-data-driven-dimensions.html">Describe a dimension as a Java level stem, and keep one <code>World</code> per dimension</a></strong></p><p>Every world this server loads is the Overworld.</p></li><li><p><strong><a href="./0005-generation-host-process.html">Run chunk generation in a host process, and keep the in-process pool as the fallback</a></strong></p><p>Generation workers are threads of the server process.</p></li><li><p><strong><a href="./0006-libdatachannel-for-nethernet-server.html">Run NetherNet on our own build of libdatachannel, and remove werift</a></strong></p><p>The server&#39;s NetherNet peers, and our client&#39;s, ran on werift, a WebRTC stack written in TypeScript that the <code>nethernet</code> package picks by default.</p></li><li><p><strong><a href="./0007-own-nethernet-protocol.html">Implement the NetherNet protocol in <code>@jsprismarine/nethernet</code></a></strong></p><p>The server and our client ran NetherNet through <code>nethernet</code> (PrismarineJS&#39;s node-nethernet), with <code>@jsprismarine/nethernet</code> beside it for HTTP signaling, the identity, the LAN advertisement and join by address.</p></li><li><p><strong><a href="./0008-shared-udp-port-in-native-code.html">Share one UDP port between RakNet and NetherNet in native code</a></strong></p><p>Bedrock Dedicated Server 1.26.70 uses <code>server-port</code> for NetherNet&#39;s UDP when <code>server-udp-ports</code> is unset.</p></li></ul></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};